import{_ as e,o as t,c as r,x as i}from"./chunks/framework.DzQQ_lrg.js";const o="/xi-kari-skill/handbook/images/history.svg",k=JSON.parse('{"title":"留下记录，与真正学会了什么","description":"学习要看更新怎样保留、怎样被调用；历史是否另有预测增量，是另一个问题。","frontmatter":{"title":"留下记录，与真正学会了什么","description":"学习要看更新怎样保留、怎样被调用；历史是否另有预测增量，是另一个问题。"},"headers":[],"relativePath":"concepts/history.md","filePath":"concepts/history.md"}'),l={name:"concepts/history.md"};function h(s,a,n,c,p,d){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="留下记录-与真正学会了什么" tabindex="-1">留下记录，与真正学会了什么 <a class="header-anchor" href="#留下记录-与真正学会了什么" aria-label="Permalink to &quot;留下记录，与真正学会了什么&quot;">​</a></h1><p>经验写进了档案，为什么还要看下一次有没有用上？</p><p><strong>学习要看更新怎样保留、怎样被调用；历史是否另有预测增量，是另一个问题。</strong></p><h2 id="从具体情景看区别" tabindex="-1">从具体情景看区别 <a class="header-anchor" href="#从具体情景看区别" aria-label="Permalink to &quot;从具体情景看区别&quot;">​</a></h2><p>沿用原文的虚拟申诉例：一次案件处理真的变了，仍要继续看这次变化有没有形成可保留的规则或状态，后来处理相似案件时有没有调用，以及预定任务结果是否出现可复核差异。载体可以是状态、参数、规则、记忆或结构；关键不是名称，而是更新实际进入后续工作。原文又举出较早经历H改变当前技能S、技能再影响结果Y的关系。</p><p>如果当前技能已经充分携带相关历史信息，知道技能之后，完整经历可能不再增加预测信息。这不取消早期经历的作用，也不取消一般学习，只说明“当前状态之外还有多少历史增量”获得了另一种答案。因此，档案存在、载体学习、额外历史增量和最终净收益要分开看，不能把其中一个当作其余几个的证明。</p><figure class="concept-figure"><img src="'+o+'" alt="经验怎样进入下一次任务"><figcaption>这是原文的载体学习机制链；每段都需要相应依据，不能凭归档跨越。</figcaption></figure><h2 id="真实材料-规程改了-是否就说明学会了" tabindex="-1">真实材料：规程改了，是否就说明学会了 <a class="header-anchor" href="#真实材料-规程改了-是否就说明学会了" aria-label="Permalink to &quot;真实材料：规程改了，是否就说明学会了&quot;">​</a></h2><p>弗林特饮水危机之后，美国环保署水务办公室在2019年为饮水热线制定了处理规程，要求追踪公众提出的关切、评估风险，并记录每条线索的处理结果。监察长在2022年的跟进审计中认定，这回应了此前的建议。（<a href="https://www.epa.gov/system/files/documents/2022-05/_epaoig_20220517-22-P-0046.pdf" target="_blank" rel="noreferrer">2022年跟进审计</a>，第15页）</p><p>这是一处有记录的规则更新，用原文§6.3的话，可以如实写成“做法已改变”。要说它构成这里讲的学习，还得看到规程在后来一批批线索中实际使用，以及处理结果相对事先说定的基线出现可复核的差异。审计核对的是规程文本和访谈，这两项都没有材料。完整记录见<a href="/xi-kari-skill/handbook/cases/flint-water-feedback.html">弗林特饮水投诉案例</a>。</p><h2 id="真实材料-没拿到执照-就等于没有学会吗" tabindex="-1">真实材料：没拿到执照，就等于没有学会吗？ <a class="header-anchor" href="#真实材料-没拿到执照-就等于没有学会吗" aria-label="Permalink to &quot;真实材料：没拿到执照，就等于没有学会吗？&quot;">​</a></h2><p>伦敦出租车学员开始训练时和三至四年后，研究者各测了一次。复测时，取得资格和没有取得资格的学员，在伦敦地标空间关系判断上都显著优于对照者；后部海马灰质体积的显著增加，却只见于取得资格的学员。（<a href="https://doi.org/10.1016/j.cub.2011.11.018" target="_blank" rel="noreferrer">Woollett与Maguire，2011</a>，第2109、2111页）</p><p>资格、任务表现和影像指标要分开看：不能用“没测到影像变化”取消已有的行为证据，也不能凭影像变化认定反馈介导学习的机制已经识别。给定当前状态之后训练历史是否另有增量，也就是§4.5的G3，这项研究没有检验。人数、失访和其他限制见<a href="/xi-kari-skill/handbook/cases/london-taxi-learning.html">伦敦出租车学员案例</a>。</p><h2 id="回到原文" tabindex="-1">回到原文 <a class="header-anchor" href="#回到原文" aria-label="Permalink to &quot;回到原文&quot;">​</a></h2><blockquote><p>一次参数变化、一次成功、一次写回或材料归档都不足以证明这条学习机制。</p></blockquote><ul><li><a href="/xi-kari-skill/handbook/theory/part-04.html#section-4-5">§4.5 历史形成、当前载体与G3条件增量</a></li><li><a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-3">§6.3 CM-LEARNING 反馈介导学习</a></li><li><a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-4">§6.4 虚拟申诉例</a></li></ul><h2 id="这处区别能说明到哪里" tabindex="-1">这处区别能说明到哪里 <a class="header-anchor" href="#这处区别能说明到哪里" aria-label="Permalink to &quot;这处区别能说明到哪里&quot;">​</a></h2><p>一般学习可以依据领域证据成立，不必先获得本框架正式机制实例身份。学习成立也不等于效果更好；当前技能充分而历史增量消失，不表示过去没有作用。</p><h2 id="接着理解" tabindex="-1">接着理解 <a class="header-anchor" href="#接着理解" aria-label="Permalink to &quot;接着理解&quot;">​</a></h2><ul><li><a href="./feedback.html">收到消息，为什么还不算有效反馈</a></li><li><a href="./chain.html">两段都有效，整条链为什么仍可能无效</a></li></ul>',20)])])}const u=e(l,[["render",h]]);export{k as __pageData,u as default};
